class Solution:
    def countKConstraintSubstrings(self, s: str, k: int) -> int:
        n = len(s)
        total = 0

        # Iterate over all possible substrings
        for i in range(n):
            zero_count = 0
            one_count = 0
            # Extend the substring from i to j
            for j in range(i, n):
                if s[j] == '0':
                    zero_count += 1
                else:
                    one_count += 1

                # Check if the substring satisfies the k-constraint
                if zero_count <= k or one_count <= k:
                    total += 1
                else:
                    # Since counts only increase as we extend, further substrings won't satisfy either condition
                    break

        return total
```

