class Solution:
    def minChanges(self, n: int, k: int) -> int:
        # If k has a bit set that n does not, it's impossible to reach k
        # because we can only flip 1->0, never 0->1.
        if (n | k) != n:
            return -1

        # Count the number of bits that are 1 in n but 0 in k
        # These are the bits we need to flip from 1 to 0.
        diff = n ^ k
        return bin(diff).count('1')
