                    direction = -direction
                    curr_idx += direction
                else:
                    # should not happen given constraints
                    return False
            # After loop, check if all zeros
            return all(x == 0 for x in nums)

        for start in zero_indices:
            # Try both directions
            if simulate(start, 1):
                count += 1
            if simulate(start, -1):
                count += 1

        return count
