class Solution:
    def minimumSubarrayLength(self, nums: List[int], k: int) -> int:
        n = len(nums)
        if k == 0:
            return 1  # Any single element is >= 0

        min_len = n + 1

        # Check all subarrays
        for i in range(n):
            or_val = 0
            for j in range(i, n):
                or_val |= nums[j]
                if or_val >= k:
                    min_len = min(min_len, j - i + 1)

