        # Convert string to list of characters for mutability
        chars = list(s)
        n = len(chars)
        swapped = False

        # Try all adjacent pairs
        for i in range(n - 1):
            # Check if both digits have the same parity
            if (int(chars[i]) % 2) == (int(chars[i + 1]) % 2):
                # If swapping makes the string lexicographically smaller, do it
                if chars[i] > chars[i + 1]:
                    chars[i], chars[i + 1] = chars[i + 1], chars[i]
                    swapped = True
                    # Since we can only swap once, break after first improvement
                    break

        return "".join(chars)
