class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        n = len(nums)
        # Simulate the queries one by one
        for k in range(len(queries)):
            l, r, val = queries[k]
            # Apply the decrement to the range [l, r]
            for i in range(l, r + 1):
                nums[i] -= val
                # If any element becomes negative, it's impossible to zero out the array
                if nums[i] < 0:
                    return -1
                # If an element becomes 0, it must stay 0 for all subsequent queries
                # because any future query covering this index will make it negative.
                # So we can mark it as already processed and skip further decrements for it.
                if nums[i] == 0:
                    nums[i] = -float('inf')  # Mark as effectively "done"

        # After all queries, check if the array is all zeros
        for x in nums:
            if x != 0:
                return -1

        return len(queries)
