import sys
import math

def count_numbers_with_9_divisors(N):
    # A number has exactly 9 divisors if its prime factorization is:
    # p1^8      -> divisors: 9
    # p1^2 * p2^2 -> divisors: (2+1)*(2+1) = 9
    # p1^4 * p2^0? No, must be p1^8 or p1^2 * p2^2
    # Actually: (a+1)*(b+1)*... = 9
    # Since 9 = 9 or 9 = 3*3
    # So forms are:
    # 1) p^8
    # 2) p1^2 * p2^2

    count = 0

    # Case 1: p^8 <= N
    # p <= N^(1/8)
    limit1 = int(N ** (1/8)) + 2
    for p in range(2, limit1):
        if is_prime(p):
            val = p ** 8
            if val <= N:
                count += 1
            else:
                break

    # Case 2: p1^2 * p2^2 <= N, with p1 < p2
    # p1 * p1 * p2 * p2 <= N => p1 * p2 <= sqrt(N)
    # But we can iterate p1 from 2 up to sqrt(N)
    # Then p2 from p1+1 up to sqrt(N / p1^2)

    limit2 = int(math.isqrt(N))
    for p1 in range(2, limit2 + 1):
        if not is_prime(p1):
            continue
        max_p2 = int(math.isqrt(N // (p1 * p1)))
        if max_p2 < p1:
            break
        for p2 in range(p1 + 1, max_p2 + 1):
            if is_prime(p2):
                val = (p1 * p1) * (p2 * p2)
                if val <= N:
                    count += 1
                else:
                    break

    return count

def is_prime(n):
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    r = int(math.isqrt(n))
    for i in range(3, r + 1, 2):
        if n % i == 0:
            return False
    return True

def main():
    N_str = sys.stdin.read().strip()
    if not N_str:
        return
    N = int(N_str)
    print(count_numbers_with_9_divisors(N))

if __name__ == "__main__":
    main()
