from typing import List

class Solution:
    def solveQueries(self, nums: List[int], queries: List[int]) -> List[int]:
        n = len(nums)
        # Group indices by value
        value_to_indices = {}
        for idx, val in enumerate(nums):
            if val not in value_to_indices:
                value_to_indices[val] = []
            value_to_indices[val].append(idx)

        def min_circular_distance(start: int, indices: List[int]) -> int:
            # Find the closest index in the circular array to 'start'
            # Consider both forward and backward distances
            best = float('inf')

            # Direct distances in linear order (forward and backward within the circle)
            for idx in indices:
                # Forward distance: from start to idx moving forward
                dist_forward = (idx - start) % n
                # Backward distance: from start to idx moving backward
                dist_backward = (start - idx) % n
                best = min(best, dist_forward, dist_backward)

            return best if best != float('inf') else -1

        answer = []
        for q in queries:
            val = nums[q]
            if val not in value_to_indices:
                answer.append(-1)
            else:
                answer.append(min_circular_distance(q, value_to_indices[val]))

        return answer
