            else:
                curr_gcd = gcd(curr_gcd, nums[i])

            if curr_lcm == 0:
                curr_lcm = nums[i]
            else:
                curr_lcm = lcm(curr_lcm, nums[i])

            prefix_gcd[i] = curr_gcd
            prefix_lcm[i] = curr_lcm

        # Precompute suffix GCDs and LCMs
        suffix_gcd = [0] * n
        suffix_lcm = [0] * n

        curr_gcd = 0
        curr_lcm = 1
        for i in range(n - 1, -1, -1):
            if curr_gcd == 0:
