            else:
                curr_lcm = lcm(curr_lcm, nums[i])

            suffix_gcd[i] = curr_gcd
            suffix_lcm[i] = curr_lcm

        # Helper to compute GCD/LCM of a subset
        def get_gcd_subset(nums_subset):
            g = 0
            for x in nums_subset:
                g = gcd(g, x)
            return g

        def get_lcm_subset(nums_subset):
            l = 1
            for x in nums_subset:
                l = lcm(l, x)
            return l

        # Option 1: Remove no element
        total_gcd = prefix_gcd[-1]
        total_lcm = prefix_lcm[-1]
        score_no_remove = total_gcd * total_lcm

        # Option 2: Remove exactly one element
        max_score = score_no_remove

        for i in range(n):
            # Compute GCD and LCM of all elements except nums[i]
            if n == 2:
                # Only one element left
                g = nums[1 - i]
