class Solution:
    def countOfSubstrings(self, word: str, k: int) -> int:
        vowels = set("aeiou")
        n = len(word)
        count = 0

        # Precompute prefix sums for vowels and consonants
        # vowel_present[i] = bitmask of vowels present in word[0:i]
        # consonant_count[i] = number of consonants in word[0:i]
        vowel_mask = [0] * (n + 1)
        consonant_count = [0] * (n + 1)

        mask = 0
        for i, ch in enumerate(word):
            if ch in vowels:
                # Map vowels to bits: a->0, e->1, i->2, o->3, u->4
                if ch == 'a':
                    mask |= 1
                elif ch == 'e':
                    mask |= 2
                elif ch == 'i':
                    mask |= 4
                elif ch == 'o':
                    mask |= 8
                elif ch == 'u':
                    mask |= 16
            else:
                mask |= 0  # consonant doesn't affect vowel mask

            vowel_mask[i+1] = mask
            consonant_count[i+1] = consonant_count[i] + (1 if ch not in vowels else 0)

        # Iterate over all possible substrings
        for left in range(n):
            # We need exactly k consonants, so the right endpoint must have
            # consonant_count[right+1] - consonant_count[left] == k
            # Also, the substring must have all 5 vowels -> mask must be 31 (11111 binary)

            current_consonants = 0
            current_mask = 0

            for right in range(left, n):
                ch = word[right]
                if ch in vowels:
                    if ch == 'a':
                        current_mask |= 1
                    elif ch == 'e':
                        current_mask |= 2
                    elif ch == 'i':
                        current_mask |= 4
                    elif ch == 'o':
                        current_mask |= 8
                    elif ch == 'u':
                        current_mask |= 16
                else:
                    current_consonants += 1

                if current_consonants == k and current_mask == 31:
                    count += 1
                elif current_consonants > k:
                    # Since consonants only increase, no need to continue this left
                    break

        return count
