import sys
from collections import deque

def solve():
    # Read all input from stdin
    input = sys.stdin.read().split()

    if not input:
        return

    iterator = iter(input)

    try:
        H = int(next(iterator))
        W = int(next(iterator))
        D = int(next(iterator))
    except StopIteration:
        return

    grid = []
    for _ in range(H):
        grid.append(next(iterator))

    # Directions: up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # Queue for BFS: store (row, col, distance)
    queue = deque()
    humidified_cells = set()

    # Initialize BFS with all humidifier cells
    for r in range(H):
        for c in range(W):
            if grid[r][c] == 'H':
                queue.append((r, c, 0))
                humidified_cells.add((r, c))

    while queue:
        r, c, dist = queue.popleft()

        # If current distance exceeds D, don't explore further from this node
        # However, since we start with 0 and only push if dist <= D, 
        # we just need to check neighbors.
        if dist == D:
            continue

        for dr, dc in directions:
            nr, nc = r + dr, c + dc

            # Check bounds
            if 0 <= nr < H and 0 <= nc < W:
                cell = grid[nr][nc]
                # Check if not a wall and not already visited (humidified)
                if cell != '#' and (nr, nc) not in humidified_cells:
                    humidified_cells.add((nr, nc))
                    queue.append((nr, nc, dist + 1))

    # Count the number of humidified floor cells ('.')
    count = 0
    for r in range(H):
        for c in range(W):
            if grid[r][c] == '.' and (r, c) in humidified_cells:
                count += 1

    print(count)

if __name__ == "__main__":
    solve()
