class Solution:
    def maxScore(self, n: int, k: int, stayScore: List[List[int]], travelScore: List[List[int]]) -> int:
        # dp[i][j] = maximum score after day i ending at city j
        # Initialize for day 0 (starting point can be any city)
        dp = [[0] * n for _ in range(k)]

        for j in range(n):
            dp[0][j] = stayScore[0][j]

        # Fill DP table for days 1 to k-1
        for i in range(1, k):
            for dest in range(n):
                # Option 1: Stay in dest city
                stay = stayScore[i][dest]

                # Option 2: Travel to dest from any previous city
                travel = max(travelScore[i-1][src] + dp[i-1][src] for src in range(n))

                dp[i][dest] = max(stay, travel)

        # The answer is the maximum value in the last day's DP table
        return max(dp[k-1])
