class Solution:
    def maxTotalReward(self, rewardValues: List[int]) -> int:
        # Sort the reward values to consider smaller ones first
        rewardValues.sort()

        # Use dynamic programming where dp[x] is a boolean indicating
        # whether total reward x is achievable.
        # The maximum possible reward is sum(rewardValues), but we can bound
        # the DP array by the maximum possible sum. Given constraints (n <= 2000,
        # values <= 2000), the max sum is 4,000,000 which is manageable.
        total_sum = sum(rewardValues)
        dp = [False] * (total_sum + 1)
        dp[0] = True

        for val in rewardValues:
            # Iterate backwards to avoid using the same element multiple times in one step
            for x in range(total_sum, val - 1, -1):
                if dp[x - val]:
                    dp[x] = True

        # The last True index is the maximum achievable reward
        for x in range(total_sum, -1, -1):
            if dp[x]:
                return x
