class Solution:
    def maximumLength(self, nums: List[int], k: int) -> int:
        n = len(nums)
        # dp[i][j] = maximum length of a good subsequence ending at index i with exactly j changes
        # j is the number of indices where seq[x] != seq[x+1] within the subsequence
        # We only need up to k changes.

        # Initialize dp table with 0
        dp = [[0] * (k + 1) for _ in range(n)]

        # Base case: each element itself is a subsequence of length 1 with 0 changes
        for i in range(n):
            dp[i][0] = 1

        # Fill dp table
        for i in range(n):
            for j in range(k + 1):
                # Option 1: Start a new subsequence at i with 0 changes
                dp[i][0] = max(dp[i][0], 1)

                # Option 2: Extend a subsequence ending at i-1
                for prev in range(i):
                    # If we extend the subsequence from prev to i
                    if dp[prev][j] > 0:
                        if nums[prev] == nums[i]:
                            # No new change, so we can extend with same j
                            dp[i][j] = max(dp[i][j], dp[prev][j] + 1)
                        else:
                            # New change occurs, so we need j+1 changes
                            if j + 1 <= k:
                                dp[i][j + 1] = max(dp[i][j + 1], dp[prev][j] + 1)

        # The answer is the maximum value in dp table for j <= k
        return max(max(row) for row in dp)
