from itertools import combinations

def solve():
    # Read N and M
    input = sys.stdin.read
    data = input().split()

    if not data:
        return

    N = int(data[0])
    M = int(data[1])

    S = []
    for i in range(N):
        S.append(data[2 + i])

    # Check all possible subsets of stands (from 1 to N)
    # Since N <= 10, we can iterate over all subsets using bitmask from 1 to (1<<N)-1
    min_stands = N  # Worst case: visit all stands

    # Total set of flavors is 0 to M-1
    all_flavors = set(range(M))

    # Iterate over all non-empty subsets of stands
    for mask in range(1, 1 << N):
        current_stands = []
        for i in range(N):
            if mask & (1 << i):
                current_stands.append(i)

        # Collect all flavors available in these stands
        collected_flavors = set()
        for idx in current_stands:
            for j in range(M):
                if S[idx][j] == 'o':
