        # Check if all flavors are collected
        if collected_flavors == all_flavors:
            num_stands = len(current_stands)
            if num_stands < min_stands:
                min_stands = num_stands
                # Optimization: if we found 1, we can't do better
                if min_stands == 1:
                    break

    print(min_stands)

if __name__ == "__main__":
