from typing import List

class Solution:
    def shortestSubstrings(self, arr: List[str]) -> List[str]:
        n = len(arr)
        # For each string, collect all its substrings with their lengths
        # We'll store (length, substring) tuples to easily find the shortest ones
        # and handle lexicographical order later.

        # Dictionary to count how many strings contain each substring
        substring_count = {}

        # Generate all substrings for all strings
        for s in arr:
            m = len(s)
            for i in range(m):
                for j in range(i + 1, m + 1):
                    sub = s[i:j]
                    substring_count[sub] = substring_count.get(sub, 0) + 1

        # For each string, find the shortest substring that appears only in that string
        answer = []
        for s in arr:
            m = len(s)
            candidates = []
            # Generate all substrings of s
            for i in range(m):
                for j in range(i + 1, m + 1):
                    sub = s[i:j]
                    # If this substring appears only in s (count == 1)
                    if substring_count[sub] == 1:
                        candidates.append((len(sub), sub))

            if not candidates:
                answer.append("")
            else:
                # Sort by length first, then lexicographically
                candidates.sort(key=lambda x: (x[0], x[1]))
                # The first one is the answer
                answer.append(candidates[0][1])

        return answer
