from typing import List

class Solution:
    def longestSubsequence(self, nums: List[int]) -> int:
        n = len(nums)
        # dp[i][d] = length of the longest valid subsequence ending at index i
        # with the last difference (absolute) equal to d.
        # Since max(nums[i]) is 300, max possible difference is 299.
        # We'll use a dictionary for each index to store max length for each difference.

        # dp[i] = {difference: length}
        dp = [{} for _ in range(n)]

        # Initialize each position with itself (subsequence of length 1)
        # No previous difference, so we don't store anything in dp[i] initially.
        # When extending, we'll compute the new difference.

        max_len = 1

        for i in range(n):
            dp[i] = {0: 1}  # placeholder; actually we will set based on transitions

            for j in range(i):
                diff = abs(nums[i] - nums[j])
                # If we extend the subsequence ending at j with last difference d,
                # and the new difference is diff, we need diff <= d.
                # So we look for all d in dp[j] such that d >= diff.
                # Among those, we take the max length + 1.

                best_prev = 0
                for d, length in dp[j].items():
                    if d >= diff:
                        if length + 1 > best_prev:
                            best_prev = length + 1

                if best_prev > 0:
                    if diff not in dp[i] or best_prev > dp[i][diff]:
                        dp[i][diff] = best_prev
                        if best_prev > max_len:
                            max_len = best_prev

        return max_len
