from typing import List

class Solution:
    def countPairs(self, nums: List[int]) -> int:
        def can_become_equal(a: int, b: int) -> bool:
            # Convert to strings to handle digits easily
            sa = str(a)
            sb = str(b)

            # If lengths differ, they can only be equal if one is a permutation of the other
            # But since we can only swap two digits, the number of digits must be the same
            if len(sa) != len(sb):
                return False

            # If numbers are already equal, they are almost equal (0 swaps)
            if sa == sb:
                return True

            # Try all possible single swaps on a and see if any equals b
            # We need to swap exactly two digits in a (or b), but swapping same-value digits
            # doesn't change the number, so we consider all pairs of indices (i, j) with i < j
            n = len(sa)
            for i in range(n):
                for j in range(i + 1, n):
                    # Create a new string with swapped digits
                    list_a = list(sa)
                    list_a[i], list_a[j] = list_a[j], list_a[i]
                    swapped_a = ''.join(list_a)

                    if swapped_a == sb:
                        return True

            return False

        count = 0
        n = len(nums)
        for i in range(n):
            for j in range(i + 1, n):
                if can_become_equal(nums[i], nums[j]):
                    count += 1

        return count
