class Solution:
    def getSmallestString(self, s: str, k: int) -> str:
        n = len(s)
        t = list(s)

        for i in range(n):
            if k <= 0:
                break
            current = ord(t[i]) - ord('a')
            target = 0  # we want 'a'

            # Calculate minimum distance from current to 'a' in cyclic order
            if current <= target:
                dist = target - current
            else:
                dist = (target - current) % 26

            if dist <= k:
                t[i] = 'a'
                k -= dist

        return "".join(t)
